import{_ as a,a as i,b as o}from"./chunks/zmp-cal-3.BgHsVRDR.js";import{_ as e,o as l,c as n,a5 as r}from"./chunks/framework.CcrBcQWS.js";const f=JSON.parse('{"title":"4. ZMP 캘리브레이션","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/guides/add-on/zmp-calibration.md","filePath":"ko/guides/add-on/zmp-calibration.md","lastUpdated":1787021357000}'),s={name:"ko/guides/add-on/zmp-calibration.md"};function d(c,t,g,p,m,h){return l(),n("div",null,[...t[0]||(t[0]=[r('<h1 id="_4-zmp-캘리브레이션" tabindex="-1">4. ZMP 캘리브레이션 <a class="header-anchor" href="#_4-zmp-캘리브레이션" aria-label="Permalink to &quot;4. ZMP 캘리브레이션&quot;">​</a></h1><p><strong>목표:</strong> 추가 모듈로 인해 변경된 무게 조건에서 로봇이 균형을 유지하도록, 영모멘트점(ZMP)을 다시 보정합니다.</p><p><strong>사전 조건:</strong> 3단계 <a href="/RBQ/nightly/ko/guides/add-on/payload-setting.html">Payload 설정</a> 완료 — 질량과 X/Y/Z 오프셋이 로봇에 등록되어 있어야 합니다.</p><h2 id="zmp-캘리브레이션의-역할" tabindex="-1">ZMP 캘리브레이션의 역할 <a class="header-anchor" href="#zmp-캘리브레이션의-역할" aria-label="Permalink to &quot;ZMP 캘리브레이션의 역할&quot;">​</a></h2><p>ZMP(Zero Moment Point) 캘리브레이션은 로봇이 서 있는 동안 지면 반력의 중심을 정렬해, 보행 중 균형을 유지할 수 있도록 합니다. Payload가 바뀌면 무게중심이 이동하므로 이 단계로 보정이 필요합니다.</p><h2 id="시작하기-전에" tabindex="-1">시작하기 전에 <a class="header-anchor" href="#시작하기-전에" aria-label="Permalink to &quot;시작하기 전에&quot;">​</a></h2><ul><li>로봇을 <strong>평탄하고 단단한 바닥</strong>에 놓으세요.</li><li>로봇에 <strong>물체나 사람이 닿지 않도록</strong> 주변을 정리하세요.</li><li>RBQGUI가 로봇에 연결되어 있고 새로운 payload가 등록된 상태여야 합니다.</li></ul><h2 id="절차" tabindex="-1">절차 <a class="header-anchor" href="#절차" aria-label="Permalink to &quot;절차&quot;">​</a></h2><ol><li><strong>RBQGUI</strong>를 실행하고 로봇에 연결합니다.</li><li>로봇을 <strong>Stance</strong>(서기) 모드로 전환합니다.</li><li><strong>Sit</strong> 버튼을 <strong>길게 누릅니다</strong>.</li></ol><figure style="text-align:center;"><img src="'+a+'" alt="Sit 버튼" style="display:block;margin:0 auto;max-width:100%;height:auto;"><figcaption style="text-align:center;">3단계 — Sit 길게 누르기</figcaption></figure><ol start="4"><li>표시되는 메뉴에서 <strong>ZMP CALIBRATE</strong>를 선택합니다.</li></ol><figure style="text-align:center;"><img src="'+i+'" alt="ZMP CALIBRATE 선택 (Recovery 메뉴)" style="display:block;margin:0 auto;max-width:100%;height:auto;"><figcaption style="text-align:center;">4단계 — ZMP CALIBRATE</figcaption></figure><ol start="5"><li>버튼이 <strong>주황색</strong>으로 바뀌면 캘리브레이션이 진행 중입니다.</li><li>완료될 때까지 <strong>로봇에 손대지 마세요</strong>.</li></ol><figure style="text-align:center;"><img src="'+o+'" alt="캘리브레이션 진행 중 (ZMP Init)" style="display:block;margin:0 auto;max-width:100%;height:auto;"><figcaption style="text-align:center;">5단계 — 캘리브레이션 진행</figcaption></figure><ol start="7"><li>버튼이 <strong>흰색</strong>으로 돌아오고 화면에 <strong>Gait: Stance</strong>가 표시되면 완료입니다.</li><li>Stance → Walk로 전환해 추가 모듈 장착 상태에서도 정상적으로 보행하는지 확인합니다.</li></ol><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">주의</p><p>캘리브레이션 중 로봇에 물건을 올리거나 밀지 마세요. 실패한 경우 절차를 다시 수행하세요.</p></div></div><h2 id="완료" tabindex="-1">완료 <a class="header-anchor" href="#완료" aria-label="Permalink to &quot;완료&quot;">​</a></h2><p>추가 모듈 장착, Payload 등록, ZMP 캘리브레이션이 모두 완료되었습니다. 이제 평소대로 동작 명령을 보낼 수 있습니다 — **<a href="/RBQ/nightly/ko/guides/common/basic-motion-command.html">기본 동작 명령</a>**으로 돌아가 로봇을 운용하세요.</p>',18)])])}const b=e(s,[["render",d]]);export{f as __pageData,b as default};
